# Eisenstein / non-Eisenstein split of the scalar cocycle Psi for general s (cone conventions of psi_q.py).
#  F_L, F_R: per-ideal weights of the cone sums E_L, E_R as functions of (C-part, narrow ray class mod m) (consistency checked);
#  non-Eis projection G = F - avg_{H} F, H = (1-sigma)Cl_m^+ (= common kernel of the sigma-invariant characters);
#  E_{.,nonEis}(tau) = sum_C sum_{B coprime} G(C, cl B) e(lambda_C N(B) tau),  lambda_C = N(C)/(4D^2), all ideals B generated by factorisation;
#  Psi_nonEis(z) = E_{L,nE}(-1/z) - (z/sqrt|det|) E_{R,nE}(z);  test  Psi_q - Psi_nonEis == Herglotz_Eis.
import cypari2, numpy as np, math, cmath, sys, itertools, pickle, sympy, time
from collections import defaultdict
from family_s import Family
pari=cypari2.Pari(); pari.allocatemem(3*10**9)
s=int(sys.argv[1]); mspec=sys.argv[2]; Qc=float(sys.argv[3]); Qev=float(sys.argv[4])
CF={7:(35,1),8:(3,4),11:(11,3)}; D0,c=CF[s]; F=Family(s); D=F.D; A=F.A
K=pari(f'bnfinit(x^2-{D0},1)'); w=pari('Mod(x,x^2-%d)'%D0)
sig=[g for g in pari.nfgaloisconj(K) if str(g)!='x'][0]
bad_p=sorted(set(int(p) for p in sympy.primefactors(2*D*D0)))
Pbad=[P for p in bad_p for P in pari.idealprimedec(K,p)]
mod=pari.idealhnf(K,1)
for tok in mspec.split(','):
    p,e=map(int,tok.split(':'))
    for P in pari.idealprimedec(K,p): mod=pari.idealmul(K,mod,pari.idealpow(K,P,e))
bnr=pari.bnrinit(K,[mod,[1,1]],1); cyc=[int(z) for z in pari('(b)->b.cyc')(bnr)]; h=math.prod(cyc)
cl=lambda J: tuple(int(z) for z in pari.bnrisprincipal(bnr,J,0))
allc=list(itertools.product(*[range(m) for m in cyc])); cidx={x:i for i,x in enumerate(allc)}
gens=pari('(b)->b.gen')(bnr); Sg=np.array([[int(z) for z in cl(pari.nfgaloisapply(K,sig,g))] for g in gens]).T
add=lambda x,y: tuple((u+v)%m for u,v,m in zip(x,y,cyc))
img={add(tuple(int(v)%m for v,m in zip(Sg@np.array(x),cyc)),tuple((-u)%m for u,m in zip(x,cyc))) for x in allc}
H={(0,)*len(cyc)}
while True:
    new={add(u,v) for u in H for v in img}|H
    if new==H: break
    H=new
print(f"s={s} m={mspec} Cl_m^+={cyc}, |H|=|(1-sigma)G|={len(H)}, bad primes {bad_p}",flush=True)
def cone_pts(al,be,Qmax):
    r1=np.array([1,0]); r2=F.G@r1; B=int(math.sqrt(Qmax)*12)+4; n=np.arange(-4*B,4*B+1); N1,N2=np.meshgrid(n,n,indexing='ij')
    X=np.stack([al[0]+D*N1.ravel(),al[1]+D*N2.ravel()],1)
    det=r1[0]*r2[1]-r1[1]*r2[0]; sv=(X[:,0]*r2[1]-X[:,1]*r2[0])*np.sign(det); tv=(r1[0]*X[:,1]-r1[1]*X[:,0])*np.sign(det)
    X=X[(sv>0)&(tv>=0)]; Q=(X[:,0]**2+s*X[:,0]*X[:,1]+(s/2)*X[:,1]**2)/(D*D); k=(Q<=Qmax)&(Q>0); X=X[k]
    assert len(X)==0 or np.max(np.abs(X))<D*(4*B-2)
    ph=np.exp(2j*np.pi*((X@A@np.array(be))%(D*D))/(D*D)); return X,ph
def content(pts):
    Fd=defaultdict(dict); NCd={}; badc=0
    for (x1,x2),v in pts:
        J=pari.idealhnf(K,(2*int(x1)+s*int(x2))+c*int(x2)*w); Cp=[]; Jp=J; NC=1
        for P in Pbad:
            e=int(pari.idealval(K,J,P)); Cp.append(e)
            if e: Jp=pari.idealdiv(K,Jp,pari.idealpow(K,P,e)); NC*=int(pari.idealnorm(K,P))**e
        k=cl(Jp); Cp=tuple(Cp); NCd[Cp]=NC
        if k in Fd[Cp] and abs(Fd[Cp][k]-v)>1e-9: badc+=1
        Fd[Cp].setdefault(k,v)
    return Fd,NCd,badc
t0=time.time()
a=F.a%D
XL,PL=cone_pts(a,(0,0),Qc); ptsL=list(zip(map(tuple,XL),PL))
ptsR=[]
for p in F.LP:
    X,P_=cone_pts(p,(-F.a)%D,Qc); ptsR+=list(zip(map(tuple,X),P_))
FL,NCL,bL=content(ptsL); FR,NCR,bR=content(ptsR)
print(f"points L {len(ptsL)}, R {len(ptsR)}; class-function inconsistencies L {bL}, R {bR}; C-parts L {len(FL)}, R {len(FR)}  ({time.time()-t0:.0f}s)",flush=True)
# ideals coprime to bad primes, by factorisation, up to Nmax
NCmin=min(list(NCL.values())+list(NCR.values()))
Nmax=int(Qev*4*D*D/NCmin)+1
print("NCmin",NCmin,"Nmax for synthesis",Nmax,flush=True)
pid=[]
for p in sympy.primerange(2,Nmax+1):
    if p in bad_p: continue
    for P in pari.idealprimedec(K,p):
        nP=int(pari.idealnorm(K,P))
        if nP<=Nmax: pid.append((nP,np.array(cl(P))))
pid.sort(key=lambda t:t[0])
print("prime ideals",len(pid),f"({time.time()-t0:.0f}s)",flush=True)
cycv=np.array(cyc)
norms=[1]; clss=[np.zeros(len(cyc),dtype=int)]
def gen(start,n,cv):
    for i in range(start,len(pid)):
        nP,cP=pid[i]
        if n*nP>Nmax: break
        nn=n*nP; cc=(cv+cP)%cycv
        while nn<=Nmax:
            norms.append(nn); clss.append(cc); gen(i+1,nn,cc)
            nn*=nP; cc=(cc+cP)%cycv
sys.setrecursionlimit(100000); gen(0,1,np.zeros(len(cyc),dtype=int))
norms=np.array(norms); cidxs=np.array([cidx[tuple(x)] for x in clss])
print("ideals generated",len(norms),f"({time.time()-t0:.0f}s)",flush=True)
minN={}
for nn,ci in zip(norms,cidxs):
    if ci not in minN or nn<minN[ci]: minN[ci]=nn
maxmin=max(minN.values()) if len(minN)==h else float('inf')
print("max over classes of min norm",maxmin,flush=True)
Hl=list(H)
def nonEis(Fd,NCd,tag):
    out=[]; dropped=0
    for Cp,Fc in Fd.items():
        NC=NCd[Cp]; lam=NC/(4*D*D)
        if lam*1>Qev: continue
        complete = NC*maxmin<=4*D*D*Qc
        if not complete:
            # irrelevant if even the smallest contribution exceeds Qev
            mins=min(minN[cidx[k]] for k in Fc)
            dropped+=1
            raise SystemExit(f"{tag}: incomplete C-part {Cp} NC={NC} relevant (lam={lam:.3g}); raise Qc")
        Fv=np.zeros(h,complex)
        for k,v in Fc.items(): Fv[cidx[k]]=v
        Gv=Fv.copy()
        for i,x in enumerate(allc): Gv[i]=Fv[i]-np.mean([Fv[cidx[add(x,hh)]] for hh in Hl])
        out.append((lam,Gv,Fv))
    return out
GL=nonEis(FL,NCL,'L'); GR=nonEis(FR,NCR,'R')
def Eeval(G,tau,which=1):
    tot=0
    for lam,Gv,Fv in G:
        V=Gv if which==1 else Fv
        m=norms*lam<=Qev
        tot+=np.sum(V[cidxs[m]]*np.exp(2j*np.pi*lam*norms[m]*tau))
    return tot
# character content of the non-Eisenstein parts: pure (chi(d)=1) vs mixed type
Nm=int(pari.idealnorm(K,mod)); dd=cl(pari.idealhnf(K,1-1000*Nm)); dpm=cl(pari.idealhnf(K,1+1000*Nm*w))
CH=np.array(allc); CL=np.array(allc); cycv=np.array(cyc)
Mchi=np.exp(2j*np.pi*(CH/cycv)@CL.T)
chid=np.exp(2j*np.pi*(CH/cycv)@np.array(dd)); pure=np.abs(chid-1)<1e-9
chipm=np.exp(2j*np.pi*(CH/cycv)@np.array(dpm))
cont={'L':[], 'R':[]}
for tag,G in (('L',GL),('R',GR)):
    mx=0; pu=0; used=set()
    for lam,Gv,Fv in G:
        sigc=np.array([cidx[tuple(int(v)%m for v,m in zip(Sg@np.array(x),cyc))] for x in allc]); Gs=(Gv+Gv[sigc])/2
        Fh=(Mchi.conj()@Gs)/h
        mx=max(mx,np.max(np.abs(Fh[~pure])) if (~pure).any() else 0); pu=max(pu,np.max(np.abs(Fh[pure])))
        for i in np.nonzero(np.abs(Fh)>1e-9)[0]: used.add(i)
    print(f"non-Eis content (sigma-symmetrised) of E_{tag}: max |pure-type| {pu:.3e}, max |mixed-type| {mx:.3e}; characters used: {sorted(tuple(int(z) for z in CH[i]) for i in used)}",flush=True)
    cont[tag]=sorted(tuple(int(z) for z in CH[i]) for i in used)
pickle.dump({'GL':GL,'GR':GR,'cyc':cyc,'cont':cont,'mspec':mspec},open(f"ecusp_{s}.pkl","wb"))
sq=math.sqrt(abs(F.det))
from psi_q import make
Psi,_,_=make(s,Qmax=40)
import herg_s
S_,terms=herg_s.build(s,verbose=False); HE=herg_s.herglotz_eis(S_,terms)
lines=[f"s={s}: m={mspec}, |H|={len(H)}; C-parts L {len(GL)}, R {len(GR)}; synthesis up to Q<={Qev}"]
for z in (1j+0.0001,0.4+0.95j,0.6+0.85j,0.2+1.1j):
    # sanity: synthesised full E's (F instead of G) reproduce the q-series
    EL_full=Eeval(GL,-1/z,0); ER_full=Eeval(GR,z,0)
    pn=Eeval(GL,-1/z)-z/sq*Eeval(GR,z)
    p=Psi(z); he=HE(z)
    lines.append(f"z={z}: Psi_q={p:.13f}  [synth full: {EL_full-z/sq*ER_full:.13f}]  Psi_nonEis={pn:.13f}  Psi_q-Psi_nonEis={p-pn:.13f}  Herglotz_Eis={he:.13f}  |diff|={abs(p-pn-he):.2e}")
    print(lines[-1],flush=True)
open(f"ecusp_{s}.txt","w").write("\n".join(lines)+"\n")
